mapper.select:
SELECT * from ( SELECT CASE WHEN ISSUE.ISSUE_EDATE >= TO_DATE(#{platformDate},'YYYY-MM-DD') or ISSUE.TENDER_EDATE >= TO_DATE(#{platformDate},'YYYY-MM-DD') THEN '01' WHEN (ISSUE.ISSUE_EDATE < TO_DATE(#{platformDate},'YYYY-MM-DD') or ISSUE.TENDER_EDATE < TO_DATE(#{platformDate},'YYYY-MM-DD')) and PRODUCT.CIRCULATION_CODE is null THEN '02' WHEN (ISSUE.ISSUE_EDATE < TO_DATE(#{platformDate},'YYYY-MM-DD') or ISSUE.TENDER_EDATE < TO_DATE(#{platformDate},'YYYY-MM-DD')) and PRODUCT.CIRCULATION_CODE is not null THEN '03'
ELSE NULL END AS issueStage, PRODUCT_ADD.ISSUE_STATUS as issueStatus, PRODUCT.FINPROD_MARKET_ID as finprodMarketId, PRODUCT.FINPROD_ABBR as finprodAbbr, PRODUCT.TRADE_MARKET as tradeMarket, PRODUCT.REGIST_ORG as registOrg, PRODUCT.ISSUER as issuer , PRODUCT.ISSUE_TYPE as issueType, ISSUE.ISSUE_CLASS as issueClass, ISSUE.TENDER_TYPE as tenderType, ISSUE.TENDER_TARGET as tenderTarget, ISSUE.ISSUE_STYLE as issueStyle, round(ISSUE.PLAN_ISSUE_AMT/100000000,2) as planIssueAmt, case when ISSUE.ISSUE_CLASS = '02' THEN ISSUE.ISSUE_SDATE else ISSUE.TENDER_SDATE end as issueDate, ISSUE.PAY_EDATE as payEdate, ISSUE.ASSIGN_REGDATE as assignRegdate, case when PRODUCT.CIRCULATION_CODE is not null then PRODUCT.CIRCULATION_DATE else PRODUCT_ADD.LISTING_DATE end as listingDate, case when PRODUCT.CIRCULATION_CODE is not null then PRODUCT2.FINPROD_MARKET_ID else PRODUCT_ADD.APPEAR_MARKET_ID end as appearMarketId, case when PRODUCT.CIRCULATION_CODE is not null then PRODUCT2.FINPROD_ABBR else PRODUCT.FINPROD_ABBR end as appearMarketAbbr, PRODUCT_ADD.CROSS_MARKET as crossMarket, PRODUCT_ADD.CROSS_MARKET_CODE as crossMarketCode, PRODUCT.VDATE as vdate, PRODUCT.MDATE as mdate, PRODUCT_TYPE.TYPE_9 as type9, PRODUCT_TYPE.TYPE_10 as type10, PRODUCT_TYPE.TYPE_11 as type11, PRODUCT.COUPON_SPECIES as couponSpecies, PRODUCT.CCY as ccy, PRODUCT.ISSUE_PRICE as issuePrice, ISSUE.INT_TYPE as intType, ISSUE.PAY_CYCLE as payCycle, ISSUE.REFER_YIELD as referYield , round(ISSUE.MIN_PER_TAMT/100000000,2) as minPerTamt, round(ISSUE.MAX_PER_UTAMT/100000000,2) as maxPerUtamt, ZT.RATING as subRate, MCI.CUSTOMER_NAME as subRateOrg, ZX.RATING as debRate, MCIT.CUSTOMER_NAME as debRateOrg, PRODUCT.REMARK as remark, PRODUCT.FINPROD_ID as finprodId FROM FIN_PRODUCT PRODUCT LEFT JOIN FIN_PRODUCT_ADD PRODUCT_ADD ON PRODUCT.FINPROD_ID = PRODUCT_ADD.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE ISSUE ON PRODUCT.FINPROD_ID = ISSUE.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE PRODUCT_TYPE ON PRODUCT.FINPROD_ID = PRODUCT_TYPE.FINPROD_ID AND PRODUCT_TYPE.BRANCH = 0 LEFT JOIN MST_CUSTOMER_INFO CUSTOMER_INFO ON PRODUCT.ISSUER = CUSTOMER_INFO.CUSTOMER_ID LEFT JOIN FIN_PRODUCT PRODUCT2 ON PRODUCT.CIRCULATION_CODE = PRODUCT2.FINPROD_ID LEFT JOIN ( SELECT ASSET_CODE,RATING,GRADE_ORG_ID FROM ( SELECT ROW_NUMBER() OVER(PARTITION BY BRATING.O_CODE ORDER BY BRATING.O_CODE,BRATING.GRADE_DATE DESC ,BRATING.GRADE_RESULT DESC) RANK,BRATING.O_CODE AS ASSET_CODE,BRATING.GRADE_RESULT AS RATING,BRATING.GRADE_ORG_ID as GRADE_ORG_ID FROM MST_BOND_CREDIT_RATING BRATING WHERE BRATING.O_TYPE = '01' AND BRATING.GRADE_DATE <= TO_DATE(#{platformDate},'YYYY-MM-DD') ) WHERE RANK=1 ) ZT on PRODUCT.FINPROD_MARKET_ID = ZT.ASSET_CODE LEFT JOIN MST_CUSTOMER_INFO MCI ON MCI.CUSTOMER_ID=ZT.GRADE_ORG_ID LEFT JOIN ( SELECT ASSET_CODE,RATING,GRADE_ORG_ID FROM ( SELECT ROW_NUMBER() OVER(PARTITION BY BRATING.O_CODE ORDER BY BRATING.O_CODE,BRATING.GRADE_DATE DESC ,BRATING.GRADE_RESULT DESC ) RANK ,BRATING.O_CODE AS ASSET_CODE ,BRATING.GRADE_RESULT AS RATING,BRATING.GRADE_ORG_ID as GRADE_ORG_ID FROM MST_BOND_CREDIT_RATING BRATING WHERE BRATING.O_TYPE = '02' AND BRATING.GRADE_DATE <= TO_DATE(#{platformDate},'YYYY-MM-DD') ) WHERE RANK=1 ) ZX ON PRODUCT.FINPROD_MARKET_ID = ZX.ASSET_CODE LEFT JOIN MST_CUSTOMER_INFO MCIT ON MCIT.CUSTOMER_ID=ZX.GRADE_ORG_ID PRODUCT.FINPROD_TYPE2=#{finprodType2,jdbcType=VARCHAR} AND PRODUCT.TRADE_MARKET in ('01','02')
AND PRODUCT.FINPROD_MARKET_ID=#{finprodMarketId,jdbcType=VARCHAR}
AND PRODUCT.TRADE_MARKET=#{tradeMarket,jdbcType=VARCHAR}
AND PRODUCT.REGIST_ORG=#{registOrg,jdbcType=VARCHAR}
AND PRODUCT.ISSUER=#{issuer,jdbcType=VARCHAR}
AND PRODUCT.ISSUE_TYPE=#{issueType,jdbcType=VARCHAR}
AND ISSUE.ISSUE_CLASS=#{issueClass,jdbcType=VARCHAR}
AND ISSUE.TENDER_TYPE=#{tenderType,jdbcType=VARCHAR}
AND ISSUE.TENDER_TARGET=#{tenderTarget,jdbcType=VARCHAR}
AND ISSUE.ISSUE_STYLE=#{tradeMarket,jdbcType=VARCHAR}
AND (PRODUCT_TYPE.TYPE_9=#{type,jdbcType=VARCHAR} or PRODUCT_TYPE.TYPE_10=#{type,jdbcType=VARCHAR} or PRODUCT_TYPE.TYPE_11=#{type,jdbcType=VARCHAR})
AND PRODUCT.COUPON_SPECIES=#{couponSpecies,jdbcType=VARCHAR}
AND ISSUE.INT_TYPE=#{intType,jdbcType=VARCHAR}
AND ISSUE.PAY_CYCLE=#{payCycle,jdbcType=VARCHAR}
AND PRODUCT.CCY=#{ccy,jdbcType=VARCHAR}
AND PRODUCT_ADD.ISSUE_STATUS=#{couponSpecies,jdbcType=VARCHAR}
AND ISSUE.PAY_EDATE >= #{payEdateStart,jdbcType=DATE}
AND ISSUE.PAY_EDATE <= #{payEdateEnd,jdbcType=DATE}
AND PRODUCT.VDATE >= #{vdateStart,jdbcType=DATE}
AND PRODUCT.VDATE <= #{vdateEnd,jdbcType=DATE}
AND PRODUCT.MDATE >= #{mdateStart,jdbcType=DATE}
AND PRODUCT.MDATE <= #{mdateEnd,jdbcType=DATE}
) t LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'ISSUE_STAGE') E1 ON t.issueStage=E1.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'TRADE_PLACE') E2 ON t.tradeMarket=E2.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'REGIST_ORG') E3 ON t.registOrg=E2.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'RAISE_TYPE') E4 ON t.issueType=E2.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'ISSUE_CLASS') E5 ON t.issueClass=E2.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'TENDER_TYPE') E6 ON t.tenderType=E2.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'TENDER_TARGET') E7 ON t.tenderTarget=E2.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'ISSUE_STYLE') E8 ON t.issueStyle=E2.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'COUPON_SPECIES') E9 ON t.couponSpecies=E2.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'INT_TYPE') E10 ON t.intType=E2.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'CCY') E11 ON t.ccy=E2.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'ISSUE_STATUS') E12 ON t.issueStatus=E2.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'CUSTOM_ASSET_TYPE_TWO') E13 ON t.type9=E2.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'CUSTOM_ASSET_TYPE_THREE') E14 ON t.type10=E2.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'CUSTOM_ASSET_TYPE_FOUR') E15 ON t.type11=E2.ITEM_CODE
AND t.appearMarketId=#{appearMarketId,jdbcType=VARCHAR}
AND t.issueDate >= #{issueDateStart,jdbcType=DATE}
AND t.issueDate <= #{issueDateEnd,jdbcType=DATE}
AND t.listingDate >= #{listingDateStart,jdbcType=DATE}
AND t.listingDate <= #{listingDateEnd,jdbcType=DATE}
AND t.issueStage IN
#{item}
( E1.ITEM_VALUE like '%' || #{search} || '%' OR E2.ITEM_VALUE like '%' || #{search} || '%' OR E3.ITEM_VALUE like '%' || #{search} || '%' OR E4.ITEM_VALUE like '%' || #{search} || '%' OR E5.ITEM_VALUE like '%' || #{search} || '%' OR E6.ITEM_VALUE like '%' || #{search} || '%' OR E7.ITEM_VALUE like '%' || #{search} || '%' OR E8.ITEM_VALUE like '%' || #{search} || '%' OR E9.ITEM_VALUE like '%' || #{search} || '%' OR E10.ITEM_VALUE like '%' || #{search} || '%' OR E11.ITEM_VALUE like '%' || #{search} || '%' OR E12.ITEM_VALUE like '%' || #{search} || '%' OR E13.ITEM_VALUE like '%' || #{search} || '%' OR E4.ITEM_VALUE like '%' || #{search} || '%' OR E5.ITEM_VALUE like '%' || #{search} || '%' OR t.finprodMarketId like '%' || #{search} || '%' OR t.finprodAbbr like '%' || #{search} || '%' OR t.issuer like '%' || #{search} || '%' OR t.appearMarketId like '%' || #{search} || '%' OR t.crossMarket like '%' || #{search} || '%' OR t.crossMarketCode like '%' || #{search} || '%' OR t.subRate like '%' || #{search} || '%' OR t.subRateOrg like '%' || #{search} || '%' OR t.debRate like '%' || #{search} || '%' OR t.debRateOrg like '%' || #{search} || '%' OR t.remark like '%' || #{search} || '%' OR t.planIssueAmt ||''= #{search} OR t.planIssueAmt ||''= #{search} OR t.issuePrice ||''= #{search} OR t.referYield ||''= #{search} OR t.minPerTamt ||''= #{search} OR t.maxPerUtamt ||''= #{search} OR to_char(t.issueDate,'yyyy-MM-dd') = #{search} OR to_char(t.payEdate,'yyyy-MM-dd') = #{search} OR to_char(t.assignRegdate,'yyyy-MM-dd') = #{search} OR to_char(t.listingDate,'yyyy-MM-dd') = #{search} OR to_char(t.vdate,'yyyy-MM-dd') = #{search} OR to_char(t.mdate,'yyyy-MM-dd') = #{search} )
ORDER BY t.issueStage, t.issueStatus,t.issueDate, t.type9, t.type10, t.type11, t.issueClass

select sum(qty) from (
    select count(1) as qty from ETR_ENTRUST where FINPROD_ID=#{finprodId}

        and ENTRUST_STATUS not in ('05','07') 

    union all
    select count(1) as qty from WFL_ETR_ENTRUST where FINPROD_ID=#{finprodId}
    union all
    select count(1) as qty from TRD_FIN_PRODUCT_DEAL_TOTAL t
    INNER JOIN TRD_PRODUCT_DEAL  d on t.TOTLE_TRADE_ID=d.TOTLE_TRADE_ID
    where FINPROD_ID=#{finprodId}

        and IS_CANCEL ='N' 

    union all
    select count(1) as qty from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL where FINPROD_ID=#{finprodId}
)

select t.secid as id, t.SECNAME as text, t.MARKET2 as TRADE_MARKET, t.VDATE, t.MDATE, null as FINPROD_TYPE2 from INTERF_PAYHSRCSECINFO t
t.VDATE <= #{platDate,jdbcType=DATE} AND t.MDATE >= #{platDate,jdbcType=DATE}
AND t.MARKET2 not in(#{tradeMarket})
and t.secid = #{initValue}
and (t.secid like concat('%',concat(#{search},'%')) or t.SECNAME like concat('%',concat(#{search},'%')) )
union select t.FINPROD_MARKET_ID as id, t.FINPROD_ABBR as text, t.TRADE_MARKET, t.VDATE, t.MDATE, t.FINPROD_TYPE2 from FIN_PRODUCT t
AND t.VDATE <= #{platDate,jdbcType=DATE} AND t.MDATE >= #{platDate,jdbcType=DATE} AND t.FINPROD_TYPE2 = #{finprodType2}
AND t.TRADE_MARKET not in(#{tradeMarket})
and t.FINPROD_MARKET_ID = #{initValue}
and (t.FINPROD_MARKET_ID like concat('%',concat(#{search},'%')) or t.FINPROD_ABBR like concat('%',concat(#{search},'%')) )

select
    INT_RATE_ID id,
    to_char(INT_RATE,'FM99990.99999999999999') text,
    t.CCY
from MST_INT_RATE_INFO t

    AND t.EFF_DATE <= #{platDate,jdbcType=DATE}
    AND t.INT_RATE_TYPE = #{intRateType}

        and t.INT_RATE_ID = #{initValue}


        and (t.INT_RATE_ID like concat('%',concat(#{search},'%'))
                or to_char(t.INT_RATE,'FM99990.99999999999999') like concat('%',concat(#{search},'%'))
            )

select pm.STATUS status
from SYS_DATA_PROCESS_MARK pm
inner join (
    select
        max(HIS_NO)	       HIS_NO,
        WORKFLOW_ID
    from SYS_DATA_PROCESS_MARK


            PAGE_ID = #{pageId}


    group by  WORKFLOW_ID
) tempHis on  pm.HIS_NO = tempHis.HIS_NO and pm.WORKFLOW_ID = tempHis.WORKFLOW_ID


        pm.status in ('A','U','P')


        and pm.PAGE_ID = #{pageId}


        and pm.BUSINESS_DATA_PK1 = #{businessDataPk1}


        and pm.BUSINESS_DATA_PK2 = #{businessDataPk2}


        and pm.WORKFLOW_ID != #{workflowId}


order by pm.create_time desc
